# Surah An-Nahl (chapter 16) — part 9: ayat 81-90 (IDs 1982-1991)
SURAH = 16

ENTRIES = {
1982: (
"اور اللہ نے تمہارے لیے اس کی پیدا کردہ چیزوں سے سائے بنائے — اور تمہارے لیے پہاڑوں سے پناہ گاہیں بنائیں — اور تمہارے لیے لباس بنایا جو تمہیں گرمی سے بچائے اور لباس جو تمہیں جنگ میں بچائے — یوں وہ اپنی نعمت تمہارے اوپر پوری کرتا ہے — شاید تم مان جاؤ",
"""۱۔ سائے — پناہ گاہیں — گرمی سے حفاظت — جنگ میں حفاظت: اللہ کی نعمتوں کا تسلسل؛ ہر چیز اس کی عطا ہے۔
۲۔ ’’وَاللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَالًا وَجَعَلَ لَكُم مِّنَ الْجِبَالِ أَكْنَانًا وَجَعَلَ لَكُمْ سَرَابِيلَ تَقِيكُمُ الْحَرَّ وَسَرَابِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ‘‘ — اور اللہ نے تمہارے لیے اس کی پیدا کردہ چیزوں سے سائے بنائے — اور تمہارے لیے پہاڑوں سے پناہ گاہیں بنائیں — اور تمہارے لیے لباس بنایا جو تمہیں گرمی سے بچائے اور لباس جو تمہیں جنگ میں بچائے — یوں وہ اپنی نعمت تمہارے اوپر پوری کرتا ہے — شاید تم مان جاؤ — یعنی اللہ نے تمہارے لیے اپنی پیدا کردہ چیزوں سے سائے بنائے — اور تمہارے لیے پہاڑوں سے پناہ گاہیں بنائیں — اور تمہارے لیے ایسے لباس بنائے جو تمہیں گرمی سے بچائیں اور ایسے لباس جو تمہیں جنگ میں بچائیں — یوں وہ اپنی نعمت تم پر پوری کرتا ہے — شاید تم مان جاؤ۔
۳۔ عملی سبق: اللہ کی نعمتوں کی تکمیل پر شکر کرو؛ اسلام نعمتِ عظمیٰ ہے۔"""
),
1983: (
"پس اگر وہ منہ موڑیں تو آپ کی ذمہ داری صرف واضح پیغام پہنچانا ہے",
"""۱۔ رسول کا فرض صرف دعوت پہنچانا ہے؛ نتائج اللہ کے اختیار میں ہیں۔
۲۔ ’’فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْكَ الْبَلَاغُ الْمُبِينُ‘‘ — پس اگر وہ منہ موڑیں تو آپ کی ذمہ داری صرف واضح پیغام پہنچانا ہے — یعنی پس اگر وہ منہ موڑیں تو آپ کی ذمہ داری صرف پیغامِ واضح رسائی ہے۔
۳۔ عملی سبق: ہدایت پہنچاؤ — نتیجہ اپنے ہاتھ میں نہیں؛ اس پر بھروسہ اللہ پر رکھو۔"""
),
1984: (
"وہ اللہ کی نعمت جانتے ہیں پھر اس کا انکار کرتے ہیں — اور ان میں سے اکثر کافر ہیں",
"""۱۔ کفار نعمت پہچانتے ہیں مگر اس کا انکار کرتے ہیں؛ یہ معرفت اور ضد کا تضاد ہے۔
۲۔ ’’يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ الْكَافِرُونَ‘‘ — وہ اللہ کی نعمت جانتے ہیں پھر اس کا انکار کرتے ہیں — اور ان میں سے اکثر کافر ہیں — یعنی وہ اللہ کی نعمت جانتے ہیں پھر اس کا انکار کرتے ہیں — اور ان میں سے اکثر کافر ہیں۔
۳۔ عملی سبق: نعمت پہچان کر انکار کرنا شیطانی روش ہے؛ اس سے بچیں؛ شکر گذار بنیں۔"""
),
1985: (
"اور جس دن ہم ہر قوم سے ایک گواہ اٹھائیں گے — پھر کافروں کو اجازت نہیں دی جائے گی اور نہ وہ معذرت پیش کریں گے",
"""۱۔ قیامت میں ہر قوم پر ایک گواہ قائم ہوگا؛ حکم صرف اللہ کا ہوگا؛ کافروں کی فریاد کامیاب نہ ہوگی۔
۲۔ ’’وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّۃٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا وَلَا هُمْ يُسْتَعْتَبُونَ‘‘ — اور جس دن ہم ہر قوم سے ایک گواہ اٹھائیں گے — پھر کافروں کو اجازت نہیں دی جائے گی اور نہ وہ معذرت پیش کریں گے — یعنی جس دن ہم ہر قوم سے ایک گواہ اٹھائیں گے — پھر کافروں کو اجازت نہیں دی جائے گی اور نہ ان سے معذرت مانگی جائے گی۔
۳۔ عملی سبق: قیامت میں گواہ قائم ہے؛ اللہ کے ساتھ اپنا رابطہ درست رکھیں۔"""
),
1986: (
"اور جب ظالم عذاب دیکھیں گے — تو نہ ان کے لیے عذاب کم کیا جائے گا اور نہ انہیں مہلت دی جائے گی",
"""۱۔ عذاب آ جانے پر کوئی نرمی نہیں ہوگی؛ ظالم کی کوئی بات نہیں سنی جائے گی؛ شدید عذاب ہوگا۔
۲۔ ’’وَإِذَا رَأَى الَّذِينَ ظَلَمُوا الْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ‘‘ — اور جب ظالم عذاب دیکھیں گے — تو نہ ان کے لیے عذاب کم کیا جائے گا اور نہ انہیں مہلت دی جائے گی — یعنی جب ظالم عذاب دیکھیں گے — تو نہ ان کے لیے عذاب کم کیا جائے گا اور نہ انہیں مہلت دی جائے گی۔
۳۔ عملی سبق: عذاب سے پہلے توبہ کریں؛ وقت گزرنے کے بعد کوئی چانس نہیں۔"""
),
1987: (
"اور جب مشرک اپنے شرکاء دیکھیں گے تو کہیں گے اے ہمارے رب — یہ ہمارے وہ شرکاء ہیں جنہیں ہم نے آپؑ کے سوا پکارتے تھے — پس وہ ان کی طرف لفظ پھینکیں گے بے شک تم جھوٹے ہو",
"""۱۔ قیامت میں بت اور شرکاء خود نابوده ثابت ہوگی؛ مشرک کی گواہی ناکام؛ جھوٹا ثابت ہوگا۔
۲۔ ’’وَإِذَا رَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ قَالُوا رَبَّنَا هَٰؤُلَاءِ شُرَكَاؤُنَا الَّذِينَ كُنَّا نَدْعُو مِن دُونِكَ فَأَلْقَوْا إِلَيْهِمُ الْقَوْلَ إِنَّكُمْ لَكَاذِبُونَ‘‘ — اور جب مشرک اپنے شرکاء دیکھیں گے تو کہیں گے اے ہمارے رب — یہ ہمارے وہ شرکاء ہیں جنہیں ہم نے آپؐ کے سوا پکارتے تھے — پس وہ ان کی طرف لفظ پھینکیں گے بے شک تم جھوٹے ہو — یعنی جب مشرک اپنے شرکاء دیکھیں گے تو کہیں گے اے ہمارے رب — یہ ہمارے وہ شرکاء ہیں جنہیں ہم آپؐ کے سوا پکارتے تھے — پس وہ ان کی طرف لفظ پھینکیں گے بے شک تم جھوٹے ہو۔
۳۔ عملی سبق: شرک جھوٹا ہے؛ اللہ کے سامنے سارے بہانے ناکام ہو جائیں گے؛ خالص توحید اختیار کرو۔"""
),
1988: (
"اور وہ اس دن اللہ کے سامنے جھک جائیں گے — اور وہ ان سے گم ہو جائے گا جو وہ گھڑتے تھے",
"""۱۔ قیامت میں مشرکین کی بے بسی؛ سب جھک جائیں گے؛ ان کی گھڑی ہوئی باتیں گم ہو جائیں گی۔
۲۔ ’’وَأَلْقَوْا إِلَى اللَّهِ يَوْمَئِذٍ السَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ‘‘ — اور وہ اس دن اللہ کے سامنے جھک جائیں گے — اور وہ ان سے گم ہو جائے گا جو وہ گھڑتے تھے — یعنی وہ اس دن اللہ کے سامنے جھک جائیں گے — اور وہ ان سے گم ہو جائے گا جو وہ گھڑتے تھے۔
۳۔ عملی سبق: قیامت کے دن کوئی جھوٹ کام نہیں آئے گا؛ آج سچی بات کہو۔"""
),
1989: (
"جو لوگ کافر ہوئے اور اللہ کے راستے سے روکتے ہیں ہم ان کے عذاب میں اضافہ کریں گے ان کے فساد کے عوض جو وہ کرتے تھے",
"""۱۔ منکرین اور روکنے والوں کا عذاب بڑھایا جائے گا؛ یہ ان کے فساد کی سزا ہے۔
۲۔ ’’الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ بِمَا كَانُوا يُفْسِدُونَ‘‘ — جو لوگ کافر ہوئے اور اللہ کے راستے سے روکتے ہیں ہم ان کے عذاب میں اضافہ کریں گے ان کے فساد کے عوض جو وہ کرتے تھے — یعنی وہ لوگ جو کافر ہوئے اور اللہ کے راستے سے روکتے ہیں ہم ان کے عذاب میں اضافہ کریں گے ان کے فساد کے عوض۔
۳۔ عملی سبق: دوسروں کو اللہ کے راستے سے روکنا بڑا گناہ ہے؛ اپنی قسمت درست کرو۔"""
),
1990: (
"اور جس دن ہم ہر قوم سے ایک گواہ ان کے اپنے میں سے اٹھائیں گے — اور ہم آپؐ کو ان سب پر گواہ بنا کر لانے گے — اور ہم نے آپ پر کتاب نازل کی ہر چیز کا بیان — اور ہدایت اور رحمت اور مؤمنوں کے لیے بشارت",
"""۱۔ ہر قوم پر ایک گواہ ہوگا؛ آپؐ امتِ محمدؐ کے لیے گواہ ہیں؛ قرآن مکمل بیان ہے۔
۲۔ ’’وَيَوْمَ نَبْعَثُ فِي كُلِّ أُمَّۃٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰؤُلَاءِ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِّكُلِّ شَيْءٍ وَهُدًى وَرَحْمَۃً وَبُشْرَىٰ لِلْمُسْلِمِينَ‘‘ — اور جس دن ہم ہر قوم سے ایک گواہ ان کے انہی میں سے اٹھائیں گے — اور ہم آپؐ کو ان سب پر گواہ بنا کر لانے گے — اور ہم نے آپ پر کتاب نازل کی ہر چیز کا بیان — اور ہدایت اور رحمت اور مؤمنوں کے لیے بشارت — یعنی جس دن ہم ہر قوم سے ایک گواہ ان کے انہی لوگوں میں سے اٹھائیں گے — اور ہم آپؐ کو ان سب پر گواہ بنا کر لانے گے — اور ہم نے آپ پر نازل کی ہر چیز کا بیان کرنے والی کتاب — اور ہدایت اور رحمت اور مؤمنوں کے لیے بشارت۔
۳۔ عملی سبق: قیامت میں آپؐ اپنی امت کے گواہ ہیں؛ قرآن میں ہر چیز کا بیان ہے — اس سے ہدایت لو۔"""
),
1991: (
"بے شک اللہ انصاف اور احسان اور قرابت داروں کو دینے کا حکم دیتا ہے — اور بے حیائی اور برائی اور ظلم سے منع کرتا ہے — وہ تمہیں نصیحت کرتا ہے شاید تم نصیحت حاصل کرو",
"""۱۔ اللہ کے تین بڑے احکام: انصاف، احسان، صلہ رحمی؛ اور تین بڑے منع: فحش، منکر، بغاوت۔
۲۔ ’’إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَىٰ وَيَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ‘‘ — بے شک اللہ انصاف اور احسان اور قرابت داروں کو دینے کا حکم دیتا ہے — اور بے حیائی اور برائی اور ظلم سے منع کرتا ہے — وہ تمہیں نصیحت کرتا ہے شاید تم نصیحت حاصل کرو — یعنی بے شک اللہ انصاف اور احسان اور قرابت داروں کو دینے کا حکم دیتا ہے — اور بے حیائی اور برائی اور بغاوت سے منع کرتا ہے — وہ تمہیں نصیحت کرتا ہے شاید تم نصیحت حاصل کرو۔
۳۔ عملی سبق: انصاف اور احسان سب کا حق ہے؛ برائیوں اور ظلم سے بچیں؛ اللہ کی نصیحت قبول کریں۔"""
),
}
